SELECT game_id, damage_type_key, name, description, status, sort_order, created_at, updated_at
FROM public.damage_types
WHERE game_id = #{gameId}

    AND (
        strpos(lower(damage_type_key), lower(#{keyword})) > 0
        OR strpos(lower(name), lower(#{keyword})) > 0
    )


    AND status = #{status}

ORDER BY sort_order ASC, name ASC, damage_type_key ASC

SELECT game_id, damage_type_key, name, description, status, sort_order, created_at, updated_at
FROM public.damage_types
WHERE game_id = #{gameId} AND damage_type_key = #{damageTypeKey}

SELECT COUNT(1)
FROM public.damage_types
WHERE game_id = #{gameId} AND damage_type_key = #{damageTypeKey}

mapper.insert:
INSERT INTO public.damage_types (
    game_id, damage_type_key, name, description, status, sort_order
) VALUES (
    #{gameId}, #{damageTypeKey}, #{name}, #{description}, #{status}, #{sortOrder}
)
